input.newString:
func PathEscape(pth string) string {
	// Escape the hash sign before parsing, as url.Parse would otherwise
	// treat it (and anything after it) as a URL fragment.
	pth = strings.ReplaceAll(pth, "#", "%23")
	u, err := url.Parse(pth)
	if err != nil {
		panic(err)
	}
	return u.EscapedPath()
}

